import _magma as m
for depth in (10, 25, 50, 75, 100, 150, 200):
    try:
        value = 1
        for unused in range(depth):
            value = m.MSet([value])
    except Exception as error:
        print(depth, 'construct', type(error).__name__, str(error))
        continue
    mapping = m.MMap(m._ZZ, m._ZZ, lambda value: value)
    try:
        mapping(value)
        print(depth, 'accepted')
    except Exception as error:
        print(depth, 'apply', type(error).__name__, str(error))
